type Phase = 'investigation' | 'containment' | 'won' | 'lost'
type Modal = 'briefing' | 'reveal' | 'diagnosis' | 'advance' | 'complete' | 'event' | 'wrong' | 'win' | 'lost' | 'feedback' | null
type MissionAct = 'proteger' | 'investigar' | 'decidir' | 'controlar' | 'resultado'
type PilotStage = 'called' | 'field' | 'map' | 'board' | 'response' | 'result'
type Student = { name: string; semester: string; focus: string }
type Reveal = Clue | Intervention
type Area = 'investigacao' | 'conduta' | 'controle' | 'tempo' | 'diagnostico'
type Log = { id: string; area: Area; title: string; note: string; tone: 'good' | 'warn' | 'neutral' }
type Player = { playerId: string; xp: number; coins: number; completed: number[]; dailyClaimed: string; lastActiveDay: string; streak: number; bestScore: number }
type RewardSummary = { xp: number; coins: number; missionXP: number; dailyXP: number; speedXP: number; firstClear: boolean }
type Records = { summary: { players: number; active_players: number; plays: number; completed: number }; leaderboards: { score: RecordEntry[]; xp: RecordEntry[]; plays: RecordEntry[] } }
type RecordEntry = { playerId: string; displayName: string; value: number }
type ActiveGame = { missionId: number; variantId?: string | null; cycle: number; actions: number; cases: number; care: number; resources: number; clueIds: string[]; interventionIds: string[]; logs: Log[]; urgentCare: boolean; pendingLabId: string | null; phase: Extract<Phase, 'investigation' | 'containment'>; dailyMission: boolean }

const focusLabels: Record<string, string> = { clinica: 'raciocínio clínico', microbiologia: 'microbiologia', epidemiologia: 'epidemiologia', saudeColetiva: 'saúde coletiva' }
const shuffled = <T,>(items: T[]) => [...items].sort(() => Math.random() - .5)
const portraits: Record<Role, string> = { emergencia: helenaPortrait, infectologia: rafaelPortrait, epidemiologia: camilaPortrait, laboratorio: andrePortrait }
const localDay = () => new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' })
const dayBefore = (day: string) => { const [year, month, date] = day.split('-').map(Number); return new Date(Date.UTC(year, month - 1, date - 1)).toISOString().slice(0, 10) }
const newPlayer = (): Player => ({ playerId: typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : `local-${Date.now()}-${Math.random().toString(16).slice(2)}`, xp: 0, coins: 0, completed: [], dailyClaimed: '', lastActiveDay: '', streak: 0, bestScore: 0 })
const missionWithVariant = (base: Mission | null | undefined, variantId: string | null) => { if (!base || base.id !== 2 || !variantId) return base; const variant = districtVariants.find((item) => item.id === variantId); if (!variant) return base; const { id: _id, label: _label, ...content } = variant; return { ...base, ...content } }

type EpisodeLocation = { role: Role; icon: string; title: string; question: string; position: string }
type EpisodeScene = { code: string; call: string; fieldTitle: string; fieldHint: string; dialogue: string; fieldArt: string; mapArt: string; locations: EpisodeLocation[] }
