  1: { code: 'ALARME COSTEIRO', call: 'Uma enchente mudou a rotina do porto. Pacientes chegam debilitados e sua equipe precisa agir antes que a situação se espalhe.', fieldTitle: 'O atendimento está sob pressão.', fieldHint: 'Toque no ponto que precisa da primeira ordem.', dialogue: 'pessoas com desidratação precisam de cuidado imediato, mesmo antes de sabermos a causa.', fieldArt: mahanOperation, mapArt: mahanExplorationMap, locations: [{ role: 'emergencia', icon: '🩺', title: 'Atendimento', question: 'Quem precisa de cuidado agora?', position: 'location-clinic' }, { role: 'epidemiologia', icon: '💧', title: 'Ponto de água', question: 'O que conecta os casos?', position: 'location-water' }, { role: 'infectologia', icon: '🧭', title: 'Mercado', question: 'Onde a exposição aconteceu?', position: 'location-market' }, { role: 'laboratorio', icon: '🧪', title: 'Unidade móvel', question: 'Qual incerteza o exame reduz?', position: 'location-lab' }] },
